+    std::fs::write(&file, r#"{"format":"camcraft-view/1","view":{"display":"x-ray"}}"#).expect("write the newer file");
+    old.load_view_from(&file);
+    assert_eq!(old.display, DisplayMode::ShadedEdges);
+    let _ = std::fs::remove_dir_all(&dir);
+}

